args.ReplacementContent:
"/* MOVEMENT letters are smaller inside the same canvas — scale up to match PAIN */
.hero-keyword-image.movement-keyword {
  --movement-scale: 1.3;
  flex: none;
  width: auto;
  max-width: none;
  height: calc(var(--keyword-height) * var(--movement-scale));
  max-height: 370px; /* cap at native image height to prevent upscale blur */
  object-fit: contain;
  object-position: right center;
  margin-block: -4rem;
  image-rendering: -webkit-optimize-contrast;
  image-rendering: crisp-edges;
}"

args.TargetContent:
"/* MOVEMENT letters are smaller inside the same canvas — scale up to match PAIN */
.hero-keyword-image.movement-keyword {
  --movement-scale: 1.75;
